// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 sendValue) public {
        vm.assume(caller != address(0));
        sendValue = bound(sendValue, 0, 1 ether);

        vm.deal(address(this), 1 ether);
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s);

        Forwarder f = new Forwarder();

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(f), sendValue) {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = c.owner();
        if (caller != owner) {
            assertTrue(address(c).balance == 1 ether);
        } else {
            assertTrue(true);
        }
    }
}

contract Forwarder {
    fallback() external payable {}
}
